package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import com.lianxibu.site.service.jobs.ReportInputSnapshotService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;

/** Native completion input; report SourceProof below is explicitly only a fictional pure-builder boundary. */
class CatalogAnalysisReportCandidateTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisCompletionTest helper(){return new CatalogDayAnalysisCompletionTest(){@Override boolean mysql(){return CatalogAnalysisReportCandidateTest.this.mysql();}};}
    record Native(CatalogDayAnalysisCompletionTest.Fixture fixture,CatalogDayAnalysisCompletionService.Completed completed,Instant cutoff){ }
    Native nativeCompletion(String category,boolean alias){var h=helper();var f=h.fixture(category,alias);var cutoff=f.day().plusDays(1).atTime(5,0).atZone(ZoneId.of("Asia/Shanghai")).toInstant();h.observe(f,Clock.fixed(f.clock().instant().plusSeconds(5),ZoneOffset.UTC));return new Native(f,Objects.requireNonNull(f.service().find(f.day(),f.entity(),cutoff)),cutoff);}
    ReportInputSnapshotService.FrozenInput freeze(Native f,CatalogAnalysisReportCandidate.Value value){var command=new Prepare("fictional-catalog-report",1,Stage.DAILY_REPORT,f.fixture().day(),null,List.of(value.dependency()),List.of(),List.of(value.dependency().id()),false,"a".repeat(64));return new ReportInputSnapshotService((c,cutoff)->new SourceProof(cutoff,c.businessDate(),c.businessDate().plusDays(1),true,List.of(value.candidate()),List.of(),List.of(),List.of(value.dependency().id()))).freeze(command,f.cutoff());}
    @Test void FourCategoriesMapExactImmutableBodyVersionAndNativeOriginalDependency(){
        for(String category:List.of("agent","skill","workflow","model")){var f=nativeCompletion(category,false);var value=CatalogAnalysisReportCandidate.create(f.completed(),f.cutoff(),true,false);var candidate=value.candidate();assertEquals(Group.NEW_CATALOG_ANALYSIS,candidate.group());assertEquals(category,candidate.category());assertTrue(candidate.newOrReanalysisQualified());assertFalse(candidate.highValue());assertEquals(f.completed().version(),ContentVersionKey.fromJson(CanonicalJson.parse(value.referenceJson())));assertEquals(f.completed().version().bodyHash(),candidate.evidence().bodyHash());assertEquals(f.completed().bodyJson(),candidate.evidence().bodyJson());assertEquals(f.completed().availableAt(),candidate.evidence().completedAt());assertEquals(f.fixture().day(),candidate.metadata().businessDate());assertEquals(List.of(f.completed().version().inputJobId()),candidate.evidence().references());assertEquals(value.dependency().id(),f.completed().version().inputJobId());assertNull(candidate.metadata().summary());assertNull(candidate.metadata().sourceId());assertNull(candidate.metadata().occurrenceCount());assertNull(candidate.countCutoff());
            var frozen=freeze(f,value);assertTrue(frozen.hasContent());var snapshot=CanonicalJson.parse(frozen.snapshotJson());assertEquals(1,snapshot.get("members").size());assertEquals(f.completed().bodyJson(),JdbcFrozenInputs.canonical(snapshot.get("members").get(0).get("body")));assertFalse(value.toString().contains("fictional"));assertThrows(UnsupportedOperationException.class,()->candidate.evidence().references().clear());}
    }
    @Test void VersionRecommendedKeepsBothOriginalBodyCitationsWithoutInventingANewGeneration(){var f=nativeCompletion("agent",true);var value=CatalogAnalysisReportCandidate.create(f.completed(),f.cutoff(),true,false);assertEquals(2L,f.completed().reservation().generation());assertEquals(2,CanonicalJson.parse(value.candidate().evidence().bodyJson()).get("citation_ids").size());assertEquals(f.completed().version().revision(),value.candidate().metadata().revision());assertTrue(freeze(f,value).hasContent());}
    @Test void InvalidOrBlockedVersionNeverContributesBodyToTheFrozenReport(){var f=nativeCompletion("skill",false);for(boolean blocked:List.of(false,true)){var value=CatalogAnalysisReportCandidate.create(f.completed(),f.cutoff(),blocked,blocked);var frozen=freeze(f,value);assertFalse(frozen.hasContent());assertTrue(CanonicalJson.parse(frozen.snapshotJson()).get("members").isEmpty());}}
    @Test void ChangedBodySnapshotRootOrLateObservationRejectPureMapping(){var f=nativeCompletion("workflow",false);var original=f.completed();assertThrows(RuntimeException.class,()->CatalogAnalysisReportCandidate.create(original,original.availableAt().minusNanos(1000),true,false));assertThrows(RuntimeException.class,()->CatalogAnalysisReportCandidate.create(original,f.cutoff().plusNanos(1),true,false));
        var body=CanonicalJson.parse(original.bodyJson()).deepCopy();((tools.jackson.databind.node.ObjectNode)body).put("title","Fictional changed body");assertThrows(RuntimeException.class,()->CatalogAnalysisReportCandidate.create(new CatalogDayAnalysisCompletionService.Completed(original.reservation(),original.version(),original.inputHash(),JdbcFrozenInputs.canonical(body),original.snapshotJson(),original.availableAt()),f.cutoff(),true,false));
        var snapshot=CanonicalJson.parse(original.snapshotJson()).deepCopy();((tools.jackson.databind.node.ObjectNode)snapshot).put("generation",99);assertThrows(RuntimeException.class,()->CatalogAnalysisReportCandidate.create(new CatalogDayAnalysisCompletionService.Completed(original.reservation(),original.version(),original.inputHash(),original.bodyJson(),JdbcFrozenInputs.canonical(snapshot),original.availableAt()),f.cutoff(),true,false));
        var wrong=new ContentVersionKey(original.version().contentKind(),original.version().contentId(),original.version().revision(),original.version().bodyHash(),"fictional-other-root");assertThrows(RuntimeException.class,()->CatalogAnalysisReportCandidate.create(new CatalogDayAnalysisCompletionService.Completed(original.reservation(),wrong,original.inputHash(),original.bodyJson(),original.snapshotJson(),original.availableAt()),f.cutoff(),true,false));
    }
}
